  referenceName?: string
  /** `ref` ON DELETE policy (`cascade`|`restrict`|`setNull`|`setDefault`|`noAction`). */
  onDelete?: string
  /** `ref` ON UPDATE policy. */
  onUpdate?: string
  /** Whether the FK is `DEFERRABLE INITIALLY DEFERRED`. */
